for (j in seq_len(k - 1)) {
  denom <- hpx[j] - hpx[j + 1]
  ## near-equal slopes (e.g. locally linear log-density): the tangents are
  ## effectively parallel -> use the midpoint to keep boundaries ordered.
  if (abs(denom) < 1e-8 * max(1, abs(hpx[j]), abs(hpx[j + 1]))) {
    z[j] <- 0.5 * (x[j] + x[j + 1])
  } else {
    z[j] <- (hx[j + 1] - hx[j] - x[j + 1] * hpx[j + 1] + x[j] * hpx[j]) / denom
    ## for a log-concave density the intersection lies in (x[j], x[j+1]);
    ## clamp to guard against numerical-derivative noise.
    z[j] <- min(max(z[j], x[j]), x[j + 1])
  }
}

